const HOUR = 3_600_000;
function checkoutIso(reservationId: string, term: ReturnType<EffectiveCheckoutTermsProvider["getTerms"]>): string { if (term.reservationId !== reservationId || !/^\d{4}-\d{2}-\d{2}$/.test(term.checkoutDate) || !["contractual", "checkout_amendment"].includes(term.source) || !term.termVersion.trim() || !/^(11|12|13|14):00$/.test(term.checkoutTime)) throw new Error("Invalid authoritative effective Checkout terms"); const date = new Date(`${term.checkoutDate}T00:00:00.000Z`); if (Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== term.checkoutDate) throw new Error("Invalid authoritative effective Checkout date"); const [h, m] = term.checkoutTime.split(":").map(Number); return new Date(Date.UTC(Number(term.checkoutDate.slice(0, 4)), Number(term.checkoutDate.slice(5, 7)) - 1, Number(term.checkoutDate.slice(8, 10)), h - 1, m)).toISOString(); }
function operatorAllowed(contract: BookingContract, principal: CommandPrincipal): void { if (principal.role !== "operator" || !principal.id || principal.id !== contract.parties.operator.id || !principal.tenantId || principal.tenantId !== contract.tenantId) throw new Error("ACTION_NOT_AUTHORIZED"); }
function guestAllowed(contract: BookingContract, reservation: Reservation, principal: CommandPrincipal): void { if (principal.role !== "guest" || !principal.id || principal.id !== reservation.primaryGuestId || principal.id !== contract.parties.primaryGuest.id || !principal.tenantId || principal.tenantId !== contract.tenantId) throw new Error("ACTION_NOT_AUTHORIZED"); }
function safeItem(item: DepositClaimAssertionItem): void { if (Object.keys(item as object).some((key) => !["itemId", "description", "claimedAmountKobo", "evidenceReferenceIds"].includes(key))) throw new Error("Claim item contains unknown fields"); if (!item.itemId || !item.description.trim() || !Number.isInteger(item.claimedAmountKobo) || item.claimedAmountKobo <= 0 || item.claimedAmountKobo !== Math.trunc(item.claimedAmountKobo) || !Array.isArray(item.evidenceReferenceIds) || item.evidenceReferenceIds.length === 0) throw new Error("Claim item is invalid"); }
