function trustedForTenant(actor: CommandPrincipal, tenantId: string): void { if (!(actor.role === "system" || actor.role === "authorized_staff" || actor.role === "admin") || !actor.id || !tenantId || actor.tenantId !== tenantId) throw new Error("ACTION_NOT_AUTHORIZED"); }

