    const command = createPlatformCommandEnvelope({ commandName: "shortlet.deposit-claim.submit", principal, payload: { reservationId, itemCount: resolved.length } }); const record: DepositClaimProductionRecord = { claimId, reservationId, contractId: contract.contractId, tenantId: contract.tenantId ?? "", operatorId: contract.parties.operator.id, guestId: reservation.primaryGuestId, policyVersion: held.policyVersion, claimPolicyVersion, evidenceVersion: resolved.map((item) => item.evidence.evidenceVersion).join("|") || "none", depositAmountKobo: held.amountKobo, claimedAmountKobo: total, effectiveCheckoutIso: checkout, claimDeadlineIso: new Date(deadline).toISOString(), submittedAtIso: this.#clock().toISOString(), claimVersion: 1, status: "validated_notification_pending", items: resolved, notification: { status: "pending", notificationVersion: "0", deliveredAtIso: null, evidenceId: null }, responseWindowStartIso: null, responseWindowEndIso: null, guestResponse: null, initialReservedOperatorAwardKobo: total, initialApprovedAmountKobo: null, approvedOperatorAwardKobo: null, unapprovedRefundKobo: 0, finality: { finalityVersion: 1, status: "reserved", cause: null, finalizedAtIso: null, appealWindowStartsAt: null, appealWindowEndsAt: null }, history: [{ action: "claim_submitted", at: this.#clock().toISOString(), commandId: command.commandId }] };
